import{_ as r,a0 as p,w as n,s as d,ao as l,I as o,x as t,a1 as i,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何在 Linux 終端下創建新的文件系統/分區 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 終端下創建新的文件系統/分區 | LCTT (201511) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 終端下創建新的文件系統/分區 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 終端下創建新的文件系統/分區 | LCTT (201511) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201511/20151104 How to Create New File Systems or Partitions in the Terminal on Linux","title":"如何在 Linux 終端下創建新的文件系統/分區","tag":"201511","desc":""},"relativePath":"201511/20151104 How to Create New File Systems or Partitions in the Terminal on Linux.md","filePath":"[post].md"}'),m={name:"201511/20151104 How to Create New File Systems or Partitions in the Terminal on Linux.md"};function c(k,e,u,f,w,h){const s=p("Link");return n(),d("div",null,[e[13]||(e[13]=l(`<h1 id="如何在-linux-終端下創建新的文件系統-分區" tabindex="-1">如何在 Linux 終端下創建新的文件系統/分區 <a class="header-anchor" href="#如何在-linux-終端下創建新的文件系統-分區" aria-label="Permalink to “如何在 Linux 終端下創建新的文件系統/分區”">​</a></h1><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-feature-image.png" alt=""></p><p>在 Linux 中創建分區或新的文件系統通常意味着一件事：安裝 Gnome Parted 分區編輯器（GParted）。對於大多數 Linux 用户而言，這是唯一的辦法。不過，你是否考慮過在終端創建這些分區和文件系統？當然可以！以下就是方法！</p><h3 id="使用-cfdisk-創建一個基本的-linux-分區" tabindex="-1">使用 CFdisk 創建一個基本的 Linux 分區 <a class="header-anchor" href="#使用-cfdisk-創建一個基本的-linux-分區" aria-label="Permalink to “使用 CFdisk 創建一個基本的 Linux 分區”">​</a></h3><p>以下是如何在命令列中創建一個基本的 Linux 分區的正確方案。要做的第一件事就是先打開你的終端。若你已打開，你需要找到你想要創建分區的磁盤。這可以使用一個簡單的命令來找到。</p><pre><code>lsblk
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-lsblk.png" alt="cfdisk-lsblk"></p><p>當你運行了 <code>lsblk</code>，你應該會看到當前系統上每個磁盤的詳細列表。看看這個列表，然後找出你想要使用的磁盤。在本文中，我將使用 <code>sdb</code> 來進行演示。</p><p>在終端輸入這個命令。它會顯示一個功能強大的基於終端的分區編輯程序。</p><pre><code>sudo cfdisk /dev/sdb
</code></pre><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-empty-layout.png" alt="cfdisk-empty-layout"></p><p><strong>注意</strong>: 使用在 <code>lsblk</code> 命令輸出的你想要使用的磁盤來替換 <code>sdb</code>。</p><p>當輸入此命令後，你將進入分區編輯器中，然後訪問你想改變的磁盤。</p><p>由於磁盤分區的不同，這取決於用户的需求，這部分的指南將在 <strong>如何建立一個分離的 Linux home/root 分區佈局</strong>。</p><p>首先，需要創建根分區。這需要根據磁盤的字節數來進行分割。我測試的磁盤是 32 GB。</p><p>在 CFdisk 中使用鍵盤上的方向鍵選擇需要分配的空間。你找到後，請使用箭頭鍵選擇 [ NEW ]，然後按 Enter 鍵。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-create-root-partition.png" alt="cfdisk-create-root-partition"></p><p>該程序會要求你輸入分區大小。一旦你指定好大小後，按 Enter 鍵。這將被稱為根分區（或 /dev/sdb1）。</p><p>接下來該創建 home 分區（/dev/sdb2）了。你需要在 CFdisk 中再選擇一些空閒分區。使用箭頭選擇 [ NEW ] 選項，然後按 Enter 鍵。輸入你的 home 分區的大小，然後按 Enter 鍵來創建它。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-create-home-partition.png" alt="cfdisk-create-home-partition"></p><p>最後，需要創建交換分區。像前兩次一樣，先找一些空閒分區，並使用箭頭選擇 [ NEW ] 選項。之後，算下你 Linux 想使用多大的交換分區。</p><p><strong>注意</strong>: 交換分區通常和計算機的內存差不多大。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-specify-partition-type-swap.png" alt="cfdisk-specify-partition-type-swap"></p><p>現在，創建了交換分區，該指定其類型。使用上下箭頭來選擇它。之後，使用左右箭頭選擇 [ TYPE ] 。找到 Linux swap 選項，然後按 Enter 鍵。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/03/cfdisk-write-partition-table.jpg" alt="cfdisk-write-partition-table"></p><p>所有分區創建後。然後就是將其寫入到磁盤。使用右箭頭鍵，選擇 [ WRITE ] 選項，然後按 Enter 鍵。這將直接將新創建的分佈寫入到磁盤中。</p><h3 id="使用-mkfs-創建文件系統" tabindex="-1">使用 mkfs 創建文件系統 <a class="header-anchor" href="#使用-mkfs-創建文件系統" aria-label="Permalink to “使用 mkfs 創建文件系統”">​</a></h3><p>有時候，你並不需要一個整個重新分區，你只想要創建一個文件系統而已。你可以在終端直接使用 <code>mkfs</code> 命令來實現。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/cfdisk-mkfs-list-partitions-lsblk.png" alt="cfdisk-mkfs-list-partitions-lsblk"></p><p>首先，找出你要使用的磁盤。在終端輸入 <code>lsblk</code> 找出來。它會打印出列表，之後只要找到你想創建文件系統的分區或盤符。</p><p>在這個例子中，我將使用第二個硬盤的 <code>/dev/sdb1</code> 作為第一個分區。可以對 <code>/dev/sdb</code> 使用 mkfs（這將會使用整個分區）。</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/10/cfdisk-mkfs-make-file-system-ext4.png" alt="cfdisk-mkfs-make-file-system-ext4"></p><p>要在一個特定的分區上創建新文件系統，只需輸入</p><pre><code>sudo mkfs.ext4 /dev/sdb1
</code></pre><p>在終端。應當指出的是，<code>mkfs.ext4</code> 可以換成任何你想要使用的的文件系統。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>雖然使用圖形工具編輯文件系統和分區更容易，但終端可以説是更有效的。終端的加載速度更快，點擊幾個按鈕即可。GParted 和其它工具一樣，它也是一個完整的工具。我希望在本教程的幫助下，你會明白如何在終端中高效的編輯文件系統。</p><p>你是否更喜歡使用基於終端的方法在 Linux 上編輯分區？不管是不是，請在下面告訴我們。</p><hr>`,39)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),i(s,{href:"https://www.maketecheasier.com/create-file-systems-partitions-terminal-linux/"},{default:a(()=>[...e[0]||(e[0]=[t("https://www.maketecheasier.com/create-file-systems-partitions-terminal-linux/",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),i(s,{href:"https://www.maketecheasier.com/author/derrikdiener/"},{default:a(()=>[...e[2]||(e[2]=[t("Derrik Diener",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),i(s,{href:"https://github.com/strugglingyouth"},{default:a(()=>[...e[3]||(e[3]=[t("strugglingyouth",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),i(s,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),i(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創編譯，",-1)),i(s,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const b=r(m,[["render",c]]);export{L as __pageData,b as default};
